 "content": "def transform(grid):
    """Compare aligned binary fields separated by a unique solid divider."""
    h = len(grid)
    if not h:
        return []
    w = len(grid[0])
    if any(len(row) != w for row in grid):
        raise ValueError("Grid must be rectangular")

    candidates = []
    # Divider row: compare the regions above and below it.
    for r in range(1, h - 1):
        color = grid[r][0]
        if color != 0 and all(v == color for v in grid[r]):
            if all(grid[rr][c] != color for rr in range(h) if rr != r for c in range(w)):
                a, b = r, h - r - 1
                candidates.append((a != b, abs(a - b), "h", r))
    # Divider column: compare the regions to its left and right.
    for c in range(1, w - 1):
        color = grid[0][c]
        if color != 0 and all(grid[r][c] == color for r in range(h)):
            if all(grid[r][cc] != color for r in range(h) for cc in range(w) if cc != c):
                a, b = c, w - c - 1
                candidates.append((a != b, abs(a - b), "v", c))

    if not candidates:
        raise ValueError("No unique solid divider found")
    _, _, orientation, index = min(candidates)

    if orientation == "h":
        upper, lower = grid[:index], grid[index + 1:]
        n = min(len(upper), len(lower))
        return [[2 if upper[r][c] != 0 and lower[r][c] != 0 else 0
                 for c in range(w)] for r in range(n)]
    left_w, right_w = index, w - index - 1
    n = min(left_w, right_w)
    return [[2 if grid[r][c] != 0 and grid[r][index + 1 + c] != 0 else 0
             for c in range(n)] for r in range(h)]


